// TH14 v1.00b Stage 1 midstage wave 1.
// Source: st01.ecl.txt MainSub00 (754-774) + MainSub00b (776-796);
// girl closure GirlRedA01/GirlBlueA01 -> GirlA01 (8-32) / GirlA01_at (34-80).

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// TH14 synthetic appearance aliases (transcribe/th14/touhou-bullets.ecl).
const TH14_BALL2: int = 432; // native type 5, GirlA01_at etSprite(0,5,6)
const COLOR_6: int = 6;

// st01.ecl.txt:34-80 GirlA01_at. NHL only; Easy never starts this task.
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;
    var speed: fx = 1.2fx;
    var interval: int = 30;
    var delay: int = 0;
    if rank == 2 {
        shots = 5; speed = 2.4fx; interval = 60; delay = rand(60);
    } else if rank >= 3 {
        shots = 10; speed = 4fx; interval = 60; delay = rand(60);
    } else {
        delay = rand(300);
    }
    wait(delay); // source wait([-1]) before the first etOn
    for i in 0..shots {
        _ = fire(TH14_BALL2, COLOR_6, $self_x, $self_y, speed, aim_player(), none, none);
        wait(interval); // st01.ecl.txt:66-76 etOn then wait([-1])
    }
}

// st01.ecl.txt:8-32 GirlA01. mirror=1 is enmCreateM (MainSub00b); movement is
// reflected about the vertical axis, firing angles stay world-space.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24): circular radius 24/2
    set_hitbox(8fx);   // setHitbox(16,16): circular radius 16/2
    // Death callback: !L setDeath("DeadAttack1") has no target hook and the
    // invulnerable no-DPS shell never reaches it; see report.md.

    var a0: angle = 12288bam;  // moveVel(1.1780972f, 4.0f) = 67.5deg
    var a1: angle = 8192bam;   // moveVelTime(60, 0, 0.7853982f, 1.4f) = 45deg
    var a2: angle = -8192bam;  // moveVelTime(120, 0, -0.7853982f, 1.2f)
    if mirror != 0 {
        a0 = 20480bam;  // 112.5deg
        a1 = 24576bam;  // 135deg
        a2 = -24576bam; // 225deg
    }
    move_vel(0, a0, 4fx, EASE_LINEAR);
    move_vel(60, a1, 1.4fx, EASE_LINEAR);
    wait(60);
    if global(GVAR_RANK) >= 1 { spawn girl_fire(); } // !NHL async GirlA01_at
    move_vel(120, a2, 1.2fx, EASE_LINEAR);
    wait(120);

    // moveVelTime(120, 0, pi + RANDF2*0.08726646f, 0.5f): 180deg +/-5deg.
    var r1: int = rand(65536) - 32768;
    var b1: int = 32768 + (r1 * 910) / 32768;
    if mirror != 0 { b1 = -b1; }
    move_vel(120, b1 as angle, 0.5fx, EASE_LINEAR);
    wait(180);

    // moveVelTime(60, 0, pi + RANDF2*0.08726646f, 2.0f): second independent draw.
    var r2: int = rand(65536) - 32768;
    var b2: int = 32768 + (r2 * 910) / 32768;
    if mirror != 0 { b2 = -b2; }
    move_vel(60, b2 as angle, 2fx, EASE_LINEAR);
    loop { wait(1000); }
}

// st01.ecl.txt:776-796 MainSub00b: right mirror formation, 120 frames later.
async sub right_wave() {
    wait(120);
    for i in 0..14 {
        _ = spawn_enemy(192fx, -16fx, 140, 0, 0, 0, girl(1));
        wait(30);
    }
    _ = spawn_enemy(192fx, -16fx, 140, 0, 0, 0, girl(1)); // blue 1
    wait(30);
    _ = spawn_enemy(192fx, -16fx, 140, 0, 0, 0, girl(1)); // blue 2
}

// st01.ecl.txt:754-774 MainSub00: left 14 red + 2 blue, 30-frame spacing.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn right_wave();
    for i in 0..14 {
        _ = spawn_enemy(-192fx, -16fx, 140, 0, 0, 0, girl(0));
        wait(30);
    }
    _ = spawn_enemy(-192fx, -16fx, 140, 0, 0, 0, girl(0)); // blue 1
    wait(30);
    _ = spawn_enemy(-192fx, -16fx, 140, 0, 0, 0, girl(0)); // blue 2
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
